INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('configuracion', 'Configuración y cambios', 'Configuración', 'Instalación asegurada del motor, control de cambios, parches y diseño físico de las bases.');
INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('almacenamiento', 'Memoria y almacenamiento', 'Almacenamiento', 'Memoria, estructuras de almacenamiento, registro de transacciones y proyección de capacidad.');
INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('accesos', 'Accesos y privilegios', 'Accesos', 'Ciclo de vida de las cuentas, roles, accesos privilegiados y autenticación.');
INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('dato', 'Protección del dato', 'Protección', 'Cifrado, enmascaramiento en ambientes no productivos, retención y eliminación segura.');
INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('continuidad', 'Continuidad', 'Continuidad', 'Respaldo, recuperación probada, alta disponibilidad y replicación.');
INSERT INTO dominio (clave, nombre, nombre_corto, descripcion) VALUES ('vigilancia', 'Vigilancia y terceros', 'Vigilancia', 'Monitoreo, auditoría de registros, incidentes y servicios de base de datos contratados o en la nube.');
