INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (5, 'configuracion', 'Gestión de vulnerabilidades técnicas y parches', 'A.8.8; ISO/IEC 27008');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (6, 'configuracion', 'Creación de bases de datos y diseño físico', 'A.8.27, A.8.9');
