INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (8, 'almacenamiento', 'Gestión de estructuras de almacenamiento', 'A.8.6, A.8.13');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (9, 'almacenamiento', 'Administración del registro de transacciones', 'A.8.13, A.8.15');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (10, 'almacenamiento', 'Gestión de capacidad', 'A.8.6');
