INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (12, 'accesos', 'Gestión de privilegios y roles', 'A.8.2, A.5.15');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (13, 'accesos', 'Cuentas administrativas y accesos privilegiados', 'A.8.2, A.5.17, A.8.15');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (14, 'accesos', 'Autenticación y política de contraseñas', 'A.5.17, A.8.5, A.8.28');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (15, 'dato', 'Criptografía y gestión de llaves', 'A.8.24, A.8.20');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (16, 'dato', 'Enmascaramiento y ambientes no productivos', 'A.8.11, A.8.33, A.8.31');
INSERT INTO proceso (numero, clave_dominio, nombre, ancla) VALUES (23, 'dato', 'Retención, archivado y eliminación segura', 'A.5.33, A.5.34, A.8.10, A.7.14');
